package com.rustyvault.legacy;

import com.rustyvault.CustomerDirectory;

import java.sql.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * SECURE CUSTOMER DIRECTORY
 */
public class SecureCustomerDirectory implements CustomerDirectory {

    private static final String COLUMNS = "id, name, city, balance_cents";
    private final Connection conn;

    public SecureCustomerDirectory(Connection conn) {
        this.conn = conn;
    }

    private void validateId(String id) {
        if (id == null || !id.matches("\\d{1,18}")) {
            throw new IllegalArgumentException("Invalid ID");
        }
    }

    private void validateAmount(String amount) {
        if (amount == null || !amount.matches("\\d{1,18}")) {
            throw new IllegalArgumentException("Invalid amount");
        }
    }

    @Override
    public long addCustomer(String name, String city, long balanceCents) {
        if (name == null || name.isBlank() || city == null || city.isBlank() || balanceCents < 0) {
            throw new IllegalArgumentException("INVALID CUSTOMER");
        }
        String sql = "INSERT INTO customer (name, city, balance_cents) VALUES (?, ?, ?)";
        try (PreparedStatement ps = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
            ps.setString(1, name);
            ps.setString(2, city);
            ps.setLong(3, balanceCents);
            ps.executeUpdate();
            try (ResultSet rs = ps.getGeneratedKeys()) {
                if (rs.next()) {
                    return rs.getLong(1);
                } else {
                    throw new SQLException("No ID generated");
                }
            }
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    @Override
    public List<String> findByName(String name) {
        if (name == null) {
            throw new IllegalArgumentException("INVALID NAME");
        }
        return query("SELECT " + COLUMNS + " FROM customer WHERE name = ? ORDER BY id", name);
    }

    @Override
    public List<String> searchByNamePrefix(String prefix) {
        if (prefix == null) {
            throw new IllegalArgumentException("INVALID PREFIX");
        }
        // Escape special SQL LIKE characters: \, %, _
        String escapedPrefix = prefix.replace("\\", "\\\\")
                                     .replace("%", "\\%")
                                     .replace("_", "\\_");
        String sql = "SELECT " + COLUMNS + " FROM customer WHERE UPPER(name) LIKE UPPER(?) ESCAPE '\\' ORDER BY id";
        return query(sql, escapedPrefix + "%");
    }

    @Override
    public List<String> list(String sortBy, boolean descending) {
        String column;
        if ("id".equals(sortBy)) column = "id";
        else if ("name".equals(sortBy)) column = "name";
        else if ("city".equals(sortBy)) column = "city";
        else if ("balance".equals(sortBy)) column = "balance_cents";
        else throw new IllegalArgumentException("INVALID SORT KEY");

        String direction = descending ? "DESC" : "ASC";
        String sql = "SELECT " + COLUMNS + " FROM customer ORDER BY " + column + " " + direction + ", id ASC";
        return query(sql);
    }

    @Override
    public String getById(String id) {
        validateId(id);
        List<String> rows = query("SELECT " + COLUMNS + " FROM customer WHERE id = ?", id);
        return rows.isEmpty() ? null : rows.get(0);
    }

    @Override
    public List<String> findByIds(List<String> ids) {
        if (ids == null) throw new IllegalArgumentException("ID list cannot be null");
        if (ids.isEmpty()) return Collections.emptyList();

        for (String id : ids) {
            validateId(id);
        }

        StringBuilder placeholders = new StringBuilder();
        for (int i = 0; i < ids.size(); i++) {
            placeholders.append("?");
            if (i < ids.size() - 1) placeholders.append(",");
        }

        String sql = "SELECT " + COLUMNS + " FROM customer WHERE id IN (" + placeholders + ") ORDER BY id";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            for (int i = 0; i < ids.size(); i++) {
                ps.setString(i + 1, ids.get(i));
            }
            return queryRows(ps.executeQuery());
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    @Override
    public List<String> richerThan(String minBalanceCents) {
        validateAmount(minBalanceCents);
        return query("SELECT " + COLUMNS + " FROM customer WHERE balance_cents > ? ORDER BY id", minBalanceCents);
    }

    @Override
    public List<String> sameCityAs(String id) {
        validateId(id);
        String row = getById(id);
        if (row == null) {
            throw new IllegalArgumentException("UNKNOWN CUSTOMER: " + id);
        }
        String city = row.split("\\|")[2];
        String sql = "SELECT " + COLUMNS + " FROM customer WHERE city = ? AND id <> ? ORDER BY id";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, city);
            ps.setLong(2, Long.parseLong(id));
            return queryRows(ps.executeQuery());
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    @Override
    public int deleteByCity(String city) {
        if (city == null) {
            throw new IllegalArgumentException("INVALID CITY");
        }
        String sql = "DELETE FROM customer WHERE city = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, city);
            return ps.executeUpdate();
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    @Override
    public int count() {
        try (PreparedStatement ps = conn.prepareStatement("SELECT COUNT(*) FROM customer");
             ResultSet rs = ps.executeQuery()) {
            return rs.next() ? rs.getInt(1) : 0;
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    private List<String> query(String sql, Object... params) {
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            for (int i = 0; i < params.length; i++) {
                ps.setObject(i + 1, params[i]);
            }
            return queryRows(ps.executeQuery());
        } catch (SQLException e) {
            throw new IllegalStateException("SQL ERROR: " + e.getMessage());
        }
    }

    private List<String> query(String sql) {
        return query(sql, new Object[0]);
    }

    private List<String> queryRows(ResultSet rs) throws SQLException {
        List<String> rows = new ArrayList<>();
        while (rs.next()) {
            rows.add(rs.getLong(1) + "|" + rs.getString(2) + "|" + rs.getString(3) + "|" + rs.getLong(4));
        }
        return rows;
    }
}

